        int w = Integer.MAX_VALUE;
        for (int[] row : g) w = Math.min(w, row.length);
        int total = 0;
        int cells = 0;
        for (int c = 0; c < w; c++) {
            for (int r = 0; r < g.length; r++) {
                total += g[r][c];
                cells++;
            }
        }
        System.out.println(w + " " + total + " " + cells);
    }
}

