A region search starts at the top-left corner, steps only to non-zero cells that share a side, and marks each cell as it is added to the queue. What does this program print?

import java.util.ArrayDeque;
import java.util.Deque;

public class A31 {
    public static void main(String[] args) {
        int[][] g = {{1, 2, 0}, {3, 0, 0}, {0, 0, 4}};
        int rows = g.length;
        int cols = g[0].length;
        boolean[][] seen = new boolean[rows][cols];
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        seen[0][0] = true;
        int count = 0;
        int sum = 0;
        int[][] offs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cur = q.remove();
            count++;
            sum += g[cur[0]][cur[1]];
            for (int[] o : offs) {
                int nr = cur[0] + o[0];
                int nc = cur[1] + o[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !seen[nr][nc] && g[nr][nc] != 0) {
                    seen[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        System.out.println(count + " " + sum);
    }
}

